#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys

EXPECTED_HEAD = '91d9a16e2971e826c042c83f0bb95386f7e606ed'
ROOT = Path.cwd()
MARKER = 'AndroidEmu workflow identity + fixed guest geometry v1'
FILES = {
    'workflow': ROOT / '.github/workflows/build-ios.yml',
    'generator': ROOT / 'scripts/generate_project.py',
    'plist': ROOT / 'App/Info.plist',
    'runtime': ROOT / 'App/RuntimeView.swift',
    'library': ROOT / 'App/LibraryView.swift',
    'vm_h': ROOT / 'QEMUBridge/VMController.h',
    'vm_mm': ROOT / 'QEMUBridge/VMController.mm',
}
EXPECTED_BLOBS = {
    'workflow': '534bd77834ae666dc1a11f012a505e93c3d2f256',
    'generator': '267df141e79f725bfb6b76416f27d8a0d387e6c9',
    'plist': 'bba691047a63c840bb8faa90f465e31cd7bbd657',
    'runtime': '37a4e3e1c14c6b0cf03df2a3f82e60c7a22078e6',
    'library': '58a56c7cb9ed1c59a3aba7752602dd6c93d20491',
    'vm_h': '856069049367b83ea9e787ee9af0b490632a16ff',
    'vm_mm': '5aa52d6852fba0f396a5067f6e2fdc918b3b29cf',
}
NEW_CONFIGURE = ROOT / 'scripts/configure_app_build.py'
NEW_TEST = ROOT / 'Tests/test_app_customization.py'
PROJECT = ROOT / 'AndroidEmu.xcodeproj/project.pbxproj'
SCHEME = ROOT / 'AndroidEmu.xcodeproj/xcshareddata/xcschemes/AndroidEmu.xcscheme'

def die(message):
    print('ERROR: ' + message, file=sys.stderr)
    raise SystemExit(1)

def git(*args):
    return subprocess.check_output(['git', *args], text=True).strip()

if NEW_CONFIGURE.is_file() and MARKER in NEW_CONFIGURE.read_text(encoding='utf-8', errors='ignore'):
    print('OK: patch already appears applied.')
    raise SystemExit(0)

head = git('rev-parse', 'HEAD')
print('HEAD=' + head)
if head != EXPECTED_HEAD:
    die(f'wrong HEAD: expected {EXPECTED_HEAD}, got {head}')

for key, path in FILES.items():
    if not path.is_file():
        die(f'missing source file: {path}')
    actual = git('hash-object', str(path))
    expected = EXPECTED_BLOBS[key]
    if actual != expected:
        die(f'{path}: blob mismatch; expected {expected}, got {actual}')

if NEW_CONFIGURE.exists() or NEW_TEST.exists():
    die('patch-owned new file already exists; refusing to overwrite')

original = {key: path.read_text(encoding='utf-8') for key, path in FILES.items()}
project_original = PROJECT.read_bytes()
scheme_original = SCHEME.read_bytes()
edited = dict(original)

def replace_exact(key, old, new, label):
    count = edited[key].count(old)
    if count != 1:
        die(f'{label}: expected exactly 1 match, found {count}; no files changed')
    edited[key] = edited[key].replace(old, new, 1)
    print('PLAN: ' + label)

