replace_exact('vm_mm', "    // Use the active iPhone/iPad window ratio, with bounded guest pixels.\n    UIWindowScene *scene = nil;\n    for (UIScene *candidate in [UIApplication sharedApplication].connectedScenes) {\n        if ([candidate isKindOfClass:UIWindowScene.class] && candidate.activationState == UISceneActivationStateForegroundActive) {\n            scene = (UIWindowScene *)candidate; break;\n        }\n    }\n    CGSize panel = CGSizeMake(540, 960);\n    UIWindow *window = self.viewIfLoaded.window ?: scene.keyWindow;\n    if (window) {\n        // Runtime hides the status bar and fills the window. Using the\n        // library's safe area here shortens the SE panel before presentation.\n        panel = window.bounds.size;\n    } else if (scene) {\n        if (@available(iOS 26.0, *)) { panel = scene.effectiveGeometry.coordinateSpace.bounds.size; }\n        else { panel = scene.coordinateSpace.bounds.size; }\n    }\n    // Goldfish cannot hotplug panel geometry. Keep a portrait virtual panel;\n    // window rotation/resizing aspect-fits it without cropping or coordinate drift.\n    if (panel.width > panel.height) { panel = CGSizeMake(panel.height, panel.width); }\n    uint32_t height = (uint32_t)(MIN(1600, MAX(480, width * panel.height / MAX(panel.width, 1))) / 2) * 2;\n    if (self.isViewLoaded && (height != _height || width != _width)) { self.view = nil; _display = nil; _input = nil; }\n    _width = width; _height = height;\n", '    // AndroidEmu workflow identity + fixed guest geometry v1\n    //\n    // VMConfiguration already defines a complete Android LCD resolution.\n    // Do not reshape the guest LCD to the iPhone/iPad window ratio: doing so\n    // can turn 360x640 into 360x480 on 4:3 iPads, clipping boot animations and\n    // exposing old Android SystemUI to an unintended panel geometry.\n    // MetalDisplay aspect-fits this stable guest panel to the host window.\n    if (self.isViewLoaded && (height != _height || width != _width)) {\n        self.view = nil; _display = nil; _input = nil;\n    }\n    _width = width; _height = height;\n', 'VMController.mm: stop reshaping guest LCD to iOS aspect ratio')
replace_exact('vm_mm', '    // Keep the supplied kernel for ordinary configurations. The separately\n    // built HIGHMEM kernel is required above the stock kernel\'s lowmem limit.\n    ram = MIN(ram, 4080U); // ARMv7 Goldfish reserves its top 16 MiB for MMIO.\n    NSString *kernelPath = [path stringByAppendingPathComponent:@"kernel"];\n    if (ram > 760) {\n        kernelPath = [NSBundle.mainBundle pathForResource:@"goldfish-highmem" ofType:@"zImage"];\n        if (!kernelPath) {\n            _statusText = @"HIGHMEM対応カーネルが同梱されていません。最新版のIPAを使うか、メモリを760 MiB以下にしてください。";\n            return NO;\n        }\n    }\n    uint64_t available = AEAvailableMemory();\n    // Leave headroom for the renderer, disk I/O and UIKit. Never silently lower\n    // the requested memory and then report it as having been allocated.\n', '    // Android 4.x compatibility: keep the kernel shipped with that exact\n    // system image. The newer optional HIGHMEM kernel is reserved for 5/6;\n    // pairing it with old 4.x ramdisks can change their expected kernel ABI.\n    const bool android4Compat = apiLevel <= 19;\n    ram = MIN(ram, 4080U); // ARMv7 Goldfish reserves its top 16 MiB for MMIO.\n    NSString *kernelPath = [path stringByAppendingPathComponent:@"kernel"];\n    if (android4Compat) {\n        ram = MIN(ram, 760U);\n    } else if (ram > 760) {\n        kernelPath = [NSBundle.mainBundle pathForResource:@"goldfish-highmem" ofType:@"zImage"];\n        if (!kernelPath) {\n            _statusText = @"HIGHMEM対応カーネルが同梱されていません。最新版のIPAを使うか、メモリを760 MiB以下にしてください。";\n            return NO;\n        }\n    }\n    uint64_t available = AEAvailableMemory();\n    // Leave headroom for the renderer, disk I/O and UIKit. Android 4.x is the\n    // deliberate exception above: it is capped to the stock Goldfish lowmem\n    // range so the image\'s own kernel can be retained.\n', 'VMController.mm: keep Android 4.x on its stock kernel and lowmem range')
replace_exact('vm_mm', '    std::vector<std::string> args = {"AndroidEmu", "-machine", "android51,audiodev=audio,width=" + std::to_string(_width) + ",height=" + std::to_string(_height), "-cpu", "cortex-a8",\n        "-m", std::to_string(ram), "-smp", "1", "-accel", "tcg,tb-size=" + std::to_string(cache) + ",split-wx=on",\n        "-nodefaults", "-no-reboot", "-display", "none", "-serial", "null", "-monitor", "none",\n        "-audiodev", "none,id=audio", "-nic", emu::guestNICOption(),\n        "-kernel", kernelPath.UTF8String,\n        "-initrd", [path stringByAppendingPathComponent:@"ramdisk.img"].UTF8String,\n        "-append", "qemu=1 console=ttyS0 androidboot.console=ttyS0 androidboot.hardware=goldfish android.qemud=1"};\n', '    std::string kernelArgs =\n            "qemu=1 console=ttyS0 androidboot.console=ttyS0 "\n            "androidboot.hardware=goldfish android.qemud=1";\n    // Android 4.x used this explicit software-composition mode before the\n    // GLES renderer work. Keep 5/6 on the current GPU path, but restore the\n    // old Goldfish contract for API 14-19 to avoid SystemUI/HWUI regressions.\n    if (apiLevel <= 19) {\n        kernelArgs += " qemu.gles=0";\n    }\n    std::vector<std::string> args = {"AndroidEmu", "-machine", "android51,audiodev=audio,width=" + std::to_string(_width) + ",height=" + std::to_string(_height), "-cpu", "cortex-a8",\n        "-m", std::to_string(ram), "-smp", "1", "-accel", "tcg,tb-size=" + std::to_string(cache) + ",split-wx=on",\n        "-nodefaults", "-no-reboot", "-display", "none", "-serial", "null", "-monitor", "none",\n        "-audiodev", "none,id=audio", "-nic", emu::guestNICOption(),\n        "-kernel", kernelPath.UTF8String,\n        "-initrd", [path stringByAppendingPathComponent:@"ramdisk.img"].UTF8String,\n        "-append", kernelArgs};\n', 'VMController.mm: restore qemu.gles=0 only for Android 4.x')

configure_source = '#!/usr/bin/env python3\n"""Build-time app identity and optional icon generator for GitHub Actions.\n\nAndroidEmu workflow identity + fixed guest geometry v1\n"""\nimport argparse\nimport json\nfrom pathlib import Path\nimport re\nimport shutil\nimport subprocess\nimport tempfile\nimport urllib.parse\nimport urllib.request\n\nROOT = Path(__file__).resolve().parents[1]\nBUILD = ROOT / "build"\nCONFIG = BUILD / "app-customization.json"\nASSETS = BUILD / "AppAssets.xcassets"\n\nBUNDLE_RE = re.compile(r"^[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)+$")\n\ndef validate_name(value: str) -> str:\n    value = value.strip()\n    if not value or len(value) > 64:\n        raise ValueError("App name must contain 1..64 characters")\n    if any(ord(ch) < 32 or ord(ch) == 127 for ch in value):\n        raise ValueError("App name must not contain control characters")\n    return value\n\ndef validate_bundle_id(value: str) -> str:\n    value = value.strip()\n    if len(value) > 255 or not BUNDLE_RE.fullmatch(value):\n        raise ValueError("Bundle ID must look like com.example.app")\n    return value\n\ndef download_icon(url: str, destination: Path) -> None:\n    parsed = urllib.parse.urlparse(url)\n    if parsed.scheme != "https" or not parsed.netloc:\n        raise ValueError("Icon URL must be HTTPS")\n    request = urllib.request.Request(url, headers={"User-Agent": "AndroidEmu-CI/1"})\n    limit = 20 * 1024 * 1024\n    total = 0\n    with urllib.request.urlopen(request, timeout=45) as response, destination.open("wb") as out:\n        final = urllib.parse.urlparse(response.geturl())\n        if final.scheme != "https":\n            raise ValueError("Icon redirect must remain HTTPS")\n        while True:\n            chunk = response.read(1024 * 1024)\n            if not chunk:\n                break\n            total += len(chunk)\n            if total > limit:\n                raise ValueError("Icon download exceeds 20 MiB")\n            out.write(chunk)\n    if total == 0:\n        raise ValueError("Icon download is empty")\n\ndef image_dimensions(path: Path) -> tuple[int, int]:\n    output = subprocess.check_output(\n        ["sips", "-g", "pixelWidth", "-g", "pixelHeight", str(path)],\n        text=True,\n        stderr=subprocess.STDOUT,\n    )\n    values = {}\n    for line in output.splitlines():\n        if ":" in line:\n            key, value = line.split(":", 1)\n            key = key.strip()\n            value = value.strip()\n            if value.isdigit():\n                values[key] = int(value)\n    try:\n        return values["pixelWidth"], values["pixelHeight"]\n    except KeyError as exc:\n        raise ValueError("Unable to read icon dimensions with sips") from exc\n\ndef build_icon_catalog(url: str) -> None:\n    if shutil.which("sips") is None:\n        raise RuntimeError("Custom icons require macOS sips")\n    with tempfile.TemporaryDirectory(prefix="androidemu-icon-") as folder:\n        folder = Path(folder)\n        source = folder / "source-icon"\n        square = folder / "square.png"\n        download_icon(url, source)\n        width, height = image_dimensions(source)\n        if min(width, height) < 1024:\n            raise ValueError("Icon source must be at least 1024x1024 pixels")\n        side = min(width, height)\n        subprocess.run(\n            ["sips", "-s", "format", "png",\n             "--cropToHeightWidth", str(side), str(side),\n             str(source), "--out", str(square)],\n            check=True,\n            stdout=subprocess.DEVNULL,\n        )\n\n        appicon = ASSETS / "AppIcon.appiconset"\n        shutil.rmtree(ASSETS, ignore_errors=True)\n        appicon.mkdir(parents=True)\n        entries = [\n            ("iphone", "20x20", "2x", 40),\n            ("iphone", "20x20", "3x", 60),\n            ("iphone", "29x29", "2x", 58),\n            ("iphone", "29x29", "3x", 87),\n            ("iphone", "40x40", "2x", 80),\n            ("iphone", "40x40", "3x", 120),\n            ("iphone", "60x60", "2x", 120),\n            ("iphone", "60x60", "3x", 180),\n            ("ipad", "20x20", "1x", 20),\n            ("ipad", "20x20", "2x", 40),\n            ("ipad", "29x29", "1x", 29),\n            ("ipad", "29x29", "2x", 58),\n            ("ipad", "40x40", "1x", 40),\n            ("ipad", "40x40", "2x", 80),\n            ("ipad", "76x76", "1x", 76),\n            ("ipad", "76x76", "2x", 152),\n            ("ipad", "83.5x83.5", "2x", 167),\n            ("ios-marketing", "1024x1024", "1x", 1024),\n        ]\n        for pixels in sorted({entry[3] for entry in entries}):\n            destination = appicon / f"icon_{pixels}.png"\n            subprocess.run(\n                ["sips", "-s", "format", "png",\n                 "--resampleHeightWidth", str(pixels), str(pixels),\n                 str(square), "--out", str(destination)],\n                check=True,\n                stdout=subprocess.DEVNULL,\n            )\n        contents = {\n            "images": [\n                {"filename": f"icon_{pixels}.png",\n                 "idiom": idiom, "scale": scale, "size": size}\n                for idiom, size, scale, pixels in entries\n            ],\n            "info": {"author": "xcode", "version": 1},\n        }\n        (appicon / "Contents.json").write_text(\n            json.dumps(contents, indent=2) + "\\n", encoding="utf-8"\n        )\n        (ASSETS / "Contents.json").write_text(\n            json.dumps({"info": {"author": "xcode", "version": 1}}, indent=2) + "\\n",\n            encoding="utf-8",\n        )\n\ndef configure(name: str, bundle_id: str, icon_url: str) -> None:\n    name = validate_name(name)\n    bundle_id = validate_bundle_id(bundle_id)\n    icon_url = icon_url.strip()\n    BUILD.mkdir(parents=True, exist_ok=True)\n    if icon_url:\n        build_icon_catalog(icon_url)\n    else:\n        shutil.rmtree(ASSETS, ignore_errors=True)\n    CONFIG.write_text(\n        json.dumps(\n            {\n                "app_name": name,\n                "bundle_id": bundle_id,\n                "custom_icon": bool(icon_url),\n            },\n            ensure_ascii=False,\n            indent=2,\n        ) + "\\n",\n        encoding="utf-8",\n    )\n    print(f"Configured app name: {name}")\n    print(f"Configured bundle ID: {bundle_id}")\n    print("Custom icon:", "yes" if icon_url else "no")\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--name", default="AndroidEmu")\n    parser.add_argument("--bundle-id", default="org.androidemu.app")\n    parser.add_argument("--icon-url", default="")\n    args = parser.parse_args()\n    configure(args.name, args.bundle_id, args.icon_url)\n\nif __name__ == "__main__":\n    main()\n'
test_source = 'import importlib.util\nimport unittest\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nspec = importlib.util.spec_from_file_location(\n    "configure_app_build", ROOT / "scripts/configure_app_build.py"\n)\nmodule = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(module)\n\nclass AppCustomizationTests(unittest.TestCase):\n    def test_valid_identity(self):\n        self.assertEqual(module.validate_name("Android Test"), "Android Test")\n        self.assertEqual(\n            module.validate_bundle_id("com.example.android-test"),\n            "com.example.android-test",\n        )\n\n    def test_invalid_name(self):\n        for value in ["", "x" * 65, "bad\\nname"]:\n            with self.subTest(value=value), self.assertRaises(ValueError):\n                module.validate_name(value)\n\n    def test_invalid_bundle_id(self):\n        for value in ["app", ".com.example", "com..example", "com.example_app"]:\n            with self.subTest(value=value), self.assertRaises(ValueError):\n                module.validate_bundle_id(value)\n\nif __name__ == "__main__":\n    unittest.main()\n'

